 ing=["600 g;Hähnchenbrustfilet;F","1;Süßkartoffel (ca. 500 g);G","1;Zwiebel;G","1 Stück (20 g);Ingwer;G","1 EL;Rapsöl;V","1 EL;mildes Currypulver;V","1 Dose (400 ml);Kokosmilch;T","200 ml;Gemüsebrühe;V","3 EL;Erdnussmus ohne Zucker;T","200 g;TK-Brokkoli;Z","1;Limette;G"],
